/* The one thing a contentEditable does not say for itself: that it can be edited.
 *
 * This component had no stylesheet at all. It rendered text that happened to be editable, and the
 * only way to find that out was to click it — which nobody does to a paragraph. "No control
 * chrome" means the field does not sit in a box all day; it does not mean the reader has to guess.
 *
 * So: a cursor that says text, a quiet ground on hover that says "this responds", and a real box
 * with the focus ring while it IS being edited, because the one moment the reader must not be in
 * doubt is when their typing is going somewhere.
 */
.inline-text {
  cursor: text;
  border-radius: var(--radius-sm);
  /* Pulled back by the same amount it pads, so the resting text sits exactly where it would
   * without this: an affordance that moves the words is one that has to be paid for on every
   * screen the component appears on. */
  padding-inline: var(--space-1);
  margin-inline: calc(var(--space-1) * -1);
  transition: background-color var(--duration-fast) var(--ease-out);
}

.inline-text:hover {
  /* NOT --muted. In dark, --muted and --background are one colour by design
     (the page has no second tier there), so a hover painted with it was
     invisible in every dark theme — the control said "this responds" and then
     did not. --surface-hover is the token for exactly this question: one stop
     off whatever surface the thing is standing on. Found 2026-08-26, by
     widening the boundary check to read every stylesheet in a folder rather
     than only the one named after it. */
  background: var(--surface-hover);
}

.inline-text:focus {
  background: var(--background);
  outline: var(--ring-width) solid var(--ring);
  outline-offset: 0;
}

@media (prefers-reduced-motion: reduce) {
  .inline-text { transition: none; }
}

import './InlineText.css'
import type { ElementType } from 'react'
import { cn } from '../lib/cn'

/* True inline editing (the vanilla `.editable` contract): the SAME element
 * becomes editable on click — same font, same layout, no control chrome.
 * Enter commits, Escape reverts, blur saves. Key it by `value` upstream so a
 * server-confirmed update re-renders the committed text.
 *
 * Copy: the accessible label names the value being edited, not the act —
 * "Recording title", not "Edit title". */
export function InlineText({
  as: Tag = 'span',
  className,
  value,
  label,
  onSave,
  onAbort,
  autoFocus,
}: {
  as?: 'h2' | 'p' | 'span'
  className?: string
  value: string
  label: string
  onSave: (next: string) => void
  /** Called when editing ends without a change (composer rows close on this). */
  onAbort?: () => void
  autoFocus?: boolean
}) {
  const Element = Tag as ElementType
  /* A heading cannot carry role="textbox" (ARIA forbids overriding it, and axe
   * fails the element). So for `as="h2"` the heading stays a heading and the
   * editable textbox is a bare inline child, which inherits the heading's font
   * and layout — visually the same element, semantically valid. */
  const Editable = (Tag === 'h2' ? 'span' : Tag) as ElementType
  const editable = (
    <Editable
      ref={(el: HTMLElement | null) => {
        if (el && autoFocus) el.focus()
      }}
      className={cn('inline-text', Tag === 'h2' ? undefined : className)}
      contentEditable
      suppressContentEditableWarning
      spellCheck={false}
      role="textbox"
      aria-label={label}
      onKeyDown={(e: React.KeyboardEvent<HTMLElement>) => {
        if (e.key === 'Enter') {
          e.preventDefault()
          ;(e.target as HTMLElement).blur()
        }
        if (e.key === 'Escape') {
          ;(e.target as HTMLElement).textContent = value
          ;(e.target as HTMLElement).blur()
        }
      }}
      onBlur={(e: React.FocusEvent<HTMLElement>) => {
        const next = (e.currentTarget.textContent ?? '').trim()
        if (next && next !== value) onSave(next)
        else {
          e.currentTarget.textContent = value
          onAbort?.()
        }
      }}
    >
      {value}
    </Editable>
  )

  if (Tag === 'h2') return <Element className={className}>{editable}</Element>
  return editable
}
